"""X0: writes docs/03_results/ASSUMPTIONS.md. Every constant is read from the code that uses it, so the table cannot drift from the simulator. Sources are "assumption" unless an opened document is named.

    python -m crashguard.rd_assumptions
"""
from __future__ import annotations

from pathlib import Path

from crashguard import capacity as CAP
from crashguard import fin_g as G
from crashguard import lora as LO
from crashguard import packet as P
from crashguard import pa_sim as PA
from crashguard import replay as RE
from crashguard import rd_policy as RP
from crashguard import world_sim as W

HDR = """# Assumptions table (simulator and model constants)

<!-- header:start -->
| Field | Value |
|---|---|
| Status | current |
| Date | 2026-11-14 |
| Owner | Mritula S |
| Scope | Every simulator and model constant used by the delivery, retry and burst studies, with its source and the results that depend on it (generated). |
| Evidence labels used | SIMULATED, ANALYTICAL |
| Abbreviations | ACK = acknowledgement frame; DP = dynamic programme; GPS = Global Positioning System; SF = spreading factor |
<!-- header:end -->

Generated by `python -m crashguard.rd_assumptions` from the constants in the code. **Source "assumption" means: chosen by the project, not taken from an opened document or measured.** Only the Semtech time-on-air formula is a published formula
(reproduced in `lora.py`; the datasheet itself was not re-opened in the redesign round, so it is listed as "formula as coded"). Every paper table that rests on the simulator points here. Nothing in this table was measured on hardware.
"""


def rows() -> list[tuple]:
    g = G.GEOM
    s = [
        ("Path-loss exponent", f"{g['n_exp']}", "assumption", "world_sim geometry; all delivery results (`pa.*`, `ar.r2.*`, `rd.*`)"),
        ("Path loss at 1 m", f"{g['pl0_db']} dB", "assumption", "same"),
        ("Transmit power", f"{g['ptx_dbm']} dBm", "assumption", "same"),
        ("Extra vehicle and body loss", f"{g['extra_loss_db']} dB", "assumption", "same"),
        ("Log-normal shadowing (static, per vehicle)", f"{g['sigma_sh_db']} dB", "assumption", "same"),
        ("Cell radius, one gateway at the centre", f"{g['R_m']:.0f} m", "assumption", "same"),
        ("Per-transmission fading", f"{CAP.SIGMA_TX_DB} dB", "assumption (capacity.py)", "collision outcomes: `pa.*`, `rd.*`"),
        ("Per-vehicle level spread (no-geometry mode)", f"{CAP.SIGMA_CAR_DB} dB", "assumption (capacity.py)", "earlier studies without geometry"),
        ("Capture rule", f"a frame survives an overlap if its level exceeds each overlapping frame by {CAP.CAPTURE_DB} dB; same SF and channel only (spreading factors are treated as orthogonal)", "assumption", "every collision count: `pa.*`, `rd.d0.c.*`, `rd.*`"),
        ("Gateway sensitivity SF7 / SF8 / SF9 / SF10 / SF11 / SF12", " / ".join(f"{W.SENS_DBM[k]}" for k in (7, 8, 9, 10, 11, 12)) + " dBm", "assumption (typical 125 kHz values, not from an opened document)", "who is in range: all geometry results"),
        ("Loss reduction per SF step above the base SF", f"x {CAP.SF_DECAY} on the per-direction loss (uplink and downlink)", "assumption (N16); the D1 table reuses it", "SF-raise policies; D1 and D2 (`rd.*`); the simulator-dependence of D1 is tested in the cross-simulator check"),
        ("Per-direction loss levels p", "design 0.1, 0.3; held-out 0.2, 0.4; DEV 0.15, 0.35, 0.55; FRESH-A drawn after the freeze around 0.15, 0.30, 0.45, 0.60", "stated stress values", "all delivery results"),
        ("Duty limit", "1% and 0.1% (old grids); DEV 1% and 0.2%; FRESH-A 0.5% and 10%; simulator default 1% (`s11_sct.DEFAULT`)", "assumption; the Indian rules for 433.05 to 434.79 MHz (G.S.R. 347(E), 2022, rule 3 row 1) allow 10 mW e.r.p. at a duty cycle of at most 10% with the observation interval not stated, so 1% is stricter (`docs/03_results/FINALIZE_INDIA_RULES.md`)", "airtime, duty exceed checks"),
        ("Time on air", "Semtech SX127x formula, 125 kHz, coding rate 4/5, 8-symbol preamble, explicit header, CRC", "formula as coded in `lora.py`", "all airtime results"),
        ("Alert / ACK / flash / heartbeat length", f"{P.ALERT_LEN} B / {P.ACK_LEN} B / {W.FLASH_LEN} B / 16 B", "project packet format (`docs/01_protocol/PACKET_FORMAT.md`)", "airtime; R2 varies the alert length"),
        ("Cluster ACK length (D2)", f"11 B header + 2 B per id + {RP.SIG_LEN} B Ed25519 signature; up to 24 ids", "design", "D2 airtime and deafness"),
        ("ACK processing delay / listen margin", f"{RE.PROC_S} s / {RE.MARGIN_S} s", "assumption", "retry timing"),
        ("Compute time before the initial send", f"{RE.COMPUTE_S} s", "assumption (not measured on the ESP32)", "latency results"),
        ("Cancel window by class (Low, Moderate, Severe, Critical)", " / ".join(f"{x:g}" for x in RE.CANCEL_S) + " s", "assumption (`docs/00_overview/ARCHITECTURE.md` range 5 to 10 s)", "severity-table delay before the initial send"),
        ("Class deadlines (Severe, Critical)", f"{RP.DEADLINE_S[2]:g} s / {RP.DEADLINE_S[3]:g} s from the crash instant", "assumption (V7 convention, reused)", "all reach-within-deadline metrics; D1 table"),
        ("Burst", "b vehicles (Critical) crash within a 10 s window starting at 600 s; b = 20 (design), 30 (held-out), 25 (DEV), drawn 18 to 26 (FRESH-A)", "assumption", "burst results"),
        ("Crash alert rate", "0.1 per vehicle per hour", "stress value, not a real crash rate", "steady-state results"),
        ("Event class pool", "real out-of-fold class pairs of the VZCrash cross-validation (no synthetic pulse)", "MEASURED_SOFTWARE pool", "class assignment, mis-triage"),
        ("Decision time pool", "early-exit decision times of the de-duplicated test events (seed 42, 5% target)", "MEASURED_SOFTWARE pool", "latency"),
        ("Simulated hours per cell", f"old grids {PA.HOURS}; DEV 100; FRESH-A 600", "design", "interval widths"),
        ("Overhear model", "a vehicle decodes a gateway ACK with probability 1 - p x SF decay and when its level at the gateway is above sensitivity", "assumption", "load index of D1, gate of D2, OS-DR"),
        ("D1 prior", "failure mean 0.3, strength 6, forgetting 0.97", "design (tunable on DEV)", "D1"),
        ("D1 retry gaps / SF steps / loss bins / load bins", f"{RP.GAPS} s / {RP.SF_STEPS} / {len(RP.L_CENTRES)} / 4", "design", "D1"),
        ("D2 defer interval (Severe, Critical)", f"{RP.DEFER_S[2]:g} s / {RP.DEFER_S[3]:g} s, at most 3 per alert", "design (scale tunable on DEV)", "D2"),
        ("D3 slots (session 2)", "slot = alert time on air + 0.02 s guard; epoch at most 5 s (but at least 2 slots); S = clip(ceil(N_hat / m), 2, 12); thr3 2, m 1, alternate SF on (DEV iteration 3); clock offset at most 5 ms; slot index = SHA-256(epoch, vehicle id) mod S", "design; thr3, m, alt tuned on DEV; the others are design constants (S_MAX = 12 written before any DEV run)", "D3 (`rd.fb.*`); the epoch cap does not hold at SF12 (V12 10.6)"),
        ("Vehicle-to-vehicle overhearing for D3 (session 2)", "a vehicle with a pending alert decodes another vehicle's alert or flash if the node-to-node link (path loss and shadowing as for the gateway) is above sensitivity and it is not transmitting; no collisions at vehicle receivers", "assumption", "D3 burst-size estimate (rarely reached three vehicles in a DEV burst hour)"),
        ("Two-stage frames (D4)", "provisional flash 14 B (R3 as registered), 24 B with an 8 B tag (D4), 97 B (task wording); confirm 97 B; CANCEL 14 B x 3; at most 4 tries; exchange success (1 - p)^2", "design (R3 values); the R3 events are the stored test events at the 1% target", "H-D4a (`rd.fb.D4a.*`)"),
        ("ns-3 scenario S-X (session 2)", "gateway at 15 m, vehicles at 1.2 m, same channel constants as the custom simulator, sensitivities patched to the custom values, RX1 0.1 s and RX2 0.2 s (policies p1, quick, d1) or 1 s and 2 s (standard LoRaWAN), ACK frame about 13 B, no flash frame, one alert per vehicle", "assumption; local ns-3 changes in `XSIM_BUILD.md`", "cross-simulator verdicts (`rd.x13.*`)"),
        ("Firmware path (D6)", "host build, double precision (bit-exact with Python); ESP32 uses a single-precision FPU, so a port needs float or fixed point (NOT_RUN)", "scope", "`rd.d6.*`; no timing claim"),
        ("Nessa-style baseline (ADDED-AFTER-SESSION-1)", "ACK timeout Ub(0) = k x time on air of the 97-byte alert (k = 1 after DEV), Lb(0) = Ub(0) / 2, doubling per stage; redundant copy after the initial retransmission of each stage with spacing U(0, A), A = 1 s after DEV; SF + 1 per stage; 12 tries; no classes, no flash", "assumption: from a secondary description (Chalmers thesis, sections 3.1 and 5.3) of Nessa et al. CNS 2020, which was not opened; k and A tuned on DEV; Lb(0) is not in the description", "`rd.fc.*`, `rd.x13.*` (Nessa rows)"),
        ("Calibration sensitivity settings (A3)", "(a) -123, -126, -129, -132, -134.5, -137 dBm; (b) -130, -132.5, -135, -137.5, -140, -142.5 dBm (ns-3 shipped gateway values; ns-3 end-device table set equal in (b)); ADR backoff off in both", "both fixed in V12 11.3 before the runs", "`rd.x1.*`, `rd.x1.b.*`"),
        ("Hostile conditions", "none in the delivery simulator (no jammer, no spoofing); security is checked in the bounded models", "scope", "H-D2c"),
    ]
    return s


def main() -> None:
    lines = [HDR, "| Constant | Value | Source | Results that depend on it |", "|---|---|---|---|"]
    for a, b, c, d in rows():
        lines.append(f"| {a} | {b} | {c} | {d} |")
    lines.append("\n`LO.DUTY` (the 10% allowance of `lora.py`, equal to the limit of rule 3 row 1 of G.S.R. 347(E), 2022, full text read on 2026-11-16) is " + f"{LO.DUTY:.0%}" + ". Regulatory duty limits are parameters, never claims.\n")
    Path("docs/03_results/ASSUMPTIONS.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("rows", len(lines) - 5)


if __name__ == "__main__":
    main()
